  document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>{const p=state.products.find(p=>p.id===b.dataset.editProduct);openDialog('Editar producto',`${field('name','Nombre','text',p.name,'required maxlength="160"')}<div class="grid2"><label>Categoría<select name="category_id"><option value="">Sin categoría</option>${options(state.categories.map(c=>[c.id,c.name]),p.category_id||'')}</select></label>${field('price','Precio general ($)','text',(p.price/100).toFixed(2),'required inputmode="decimal"')}</div><p class="note">Modificar el precio general no borra precios diferenciales existentes. Las cuentas pendientes se recalculan con el precio vigente de su colegio.</p>`,'Guardar cambios',async data=>{await api(`/products/${p.id}`,{method:'PUT',body:data});$('#dialog').close();await refresh();toast('Producto actualizado.');});});
  document.querySelectorAll('[data-school-price]').forEach(b=>b.onclick=()=>schoolPriceDialog(state.products.find(p=>p.id===b.dataset.schoolPrice)));
