function categoryDialog(category=null){const content=category?field('name','Nombre de la categoría','text',category.name,'required maxlength="80"'):`${field('name','Nueva categoría','text','','required maxlength="80"')}${state.categories.length?`<div class="category-list"><h3>Categorías existentes</h3>${state.categories.map(c=>`<div class="category-row"><span>${esc(c.name)}</span><button type="button" class="secondary" data-rename-category="${c.id}">Renombrar</button></div>`).join('')}</div>`:''}`;const form=openDialog(category?'Renombrar categoría':'Categorías',content,category?'Guardar nombre':'Crear categoría',async b=>{await api(category?`/categories/${category.id}`:'/categories',{method:category?'PUT':'POST',body:b});$('#dialog').close();await refresh();toast(category?'Categoría actualizada.':'Categoría creada.');});form.querySelectorAll('[data-rename-category]').forEach(button=>button.onclick=()=>{const item=state.categories.find(c=>c.id===button.dataset.renameCategory);$('#dialog').close();categoryDialog(item);});}
function schoolPriceDialog(product){const initialSchool=school||state.schools[0]?.id;const form=openDialog('Precio por colegio',`<p><strong>${esc(product.name)}</strong></p><label>Colegio<select name="school_id">${options(state.schools.map(s=>[s.id,s.name]),initialSchool)}</select></label>${field('price','Precio especial ($)','text',(product.price/100).toFixed(2),'required inputmode="decimal"')}<p class="note">Si no configurás un valor diferencial, se usa el precio general de ${money(product.price)}.</p><button type="button" class="danger" id="reset-school-price">Volver al precio general</button>`,'Guardar precio',async b=>{await api(`/products/${product.id}/school-price`,{method:'POST',body:b});$('#dialog').close();await refresh();toast('Precio diferencial guardado.');});const reset=$('#reset-school-price');function updateSchoolPrice(){const schoolId=form.elements.school_id.value,existing=state.school_prices.find(p=>p.product_id===product.id&&p.school_id===schoolId);form.elements.price.value=((existing?.price??product.price)/100).toFixed(2);reset.hidden=!existing;}form.elements.school_id.onchange=updateSchoolPrice;updateSchoolPrice();reset.onclick=async()=>{const schoolId=form.elements.school_id.value;try{await api(`/products/${product.id}/school-price?school_id=${encodeURIComponent(schoolId)}`,{method:'DELETE'});$('#dialog').close();await refresh();toast('Se restauró el precio general.');}catch(e){toast(e.message);}};}
const docTypeNames={invoice:'Factura',delivery_note:'Remito',order:'Pedido',other:'Otro'};
function renderDocuments(){
  $('#view').innerHTML='<div class="loading">Cargando documentos…</div>';
  api('/documents').then(list=>{if(page!=='documents')return;documents=list;
    $('#view').innerHTML=`<div class="heading"><div><div class="eyebrow">Compras y comprobantes</div><h1>Documentos</h1><p>Facturas, remitos y pedidos fotografiados.</p></div><button id="new-document">+ Cargar foto</button></div><div class="note" style="margin-bottom:22px">La lectura automática es una propuesta: revisá los datos antes de guardar. Por ahora se conserva como borrador; no registra compras, modifica precios de venta ni descuenta stock. La imagen privada se almacena en Cloudflare.</div><div class="card">${list.length?`<div class="scroll"><table><thead><tr><th>Documento</th><th>Proveedor</th><th>Fecha / número</th><th>Lectura</th><th></th></tr></thead><tbody>${list.map(d=>`<tr><td><strong>${docTypeNames[d.document_type]||'Documento'}</strong><br><small>${date(d.created_at)}</small></td><td>${esc(d.supplier||'Pendiente de revisar')}</td><td>${esc(d.document_date||'—')}<br><small>${esc(d.document_number||'Sin número')}</small></td><td><span class="badge ${d.reviewed?'green':d.ai_status==='review'?'amber':''}">${d.reviewed?'Borrador revisado':d.ai_status==='review'?'Revisar lectura':d.ai_status==='error'?'Lectura fallida':'Completar manualmente'}</span></td><td><button class="secondary" data-doc="${esc(d.id)}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay documentos','Subí una foto de una factura, remito o pedido para preparar un borrador.')}</div>`;
    $('#new-document').onclick=uploadDocument;document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>editDocument(b.dataset.doc));
  }).catch(e=>{$('#view').innerHTML=`<div class="heading"><div><div class="eyebrow">Compras y comprobantes</div><h1>Documentos</h1></div></div><p class="error">${esc(e.message)}</p><p class="muted">Si el error menciona Cloudflare R2, falta crear los depósitos privados de imágenes para dev y producción; la guía está en docs/CLOUDFLARE.md.</p>`;});
}
async function uploadDocument(){
  const form=openDialog('Cargar foto de un documento',`<p class="note">Admite JPG, PNG o WebP de hasta 3 MB. Cloudflare AI propone los datos visibles; revisalos antes de guardar.</p><label>Tipo de documento<select name="document_type">${options(Object.entries(docTypeNames))}</select></label><label>Foto del documento<input id="document-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><p class="muted">La imagen original se guarda en el espacio privado de PeloApp.</p><div id="document-upload-preview"></div>`,'Leer y revisar',async(b,f)=>{
    const file=f.elements.file.files[0];if(!file)throw Error('Elegí una foto.');const image=await prepareDocumentImage(file),payload=new FormData();payload.append('file',image,'documento.jpg');payload.append('document_type',b.document_type);
    const button=f.querySelector('[type=submit]');button.textContent='Leyendo documento…';
    let response,result;try{response=await fetch('/api/documents',{method:'POST',body:payload});try{result=await response.json();}catch{throw Error('No se pudo leer la respuesta del servidor.');}if(!response.ok)throw Error(result.error||'No se pudo cargar la foto.');}catch(error){button.textContent='Leer y revisar';throw error;}
    $('#dialog').close();documents.unshift({id:result.id,...result.data,document_date:result.data.document_date,ai_status:result.ai_status,created_at:new Date().toISOString()});editDocument(result.id,result);toast(result.ai_status==='review'?'Lectura preparada. Revisá cada campo.':'Foto guardada. Completá los datos manualmente.');
  });
  $('#document-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const image=await prepareDocumentImage(file),url=URL.createObjectURL(image);$('#document-upload-preview').innerHTML=`<img class="document-preview" src="${url}" alt="Vista previa de la foto"><p class="muted">${(image.size/1024).toFixed(0)} KB · Imagen lista para cargar</p>`;}catch(err){form.querySelector('.form-error').innerHTML=`<p class="error">${esc(err.message)}</p>`;}};
}
async function prepareDocumentImage(file){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usá una foto JPG, PNG o WebP.');
  if(file.size<=2_500_000){return file;}
  const bitmap=await createImageBitmap(file),scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob||blob.size>3*1024*1024)throw Error('La imagen sigue siendo demasiado pesada. Elegí una foto más liviana.');return new File([blob],'documento.jpg',{type:'image/jpeg'});
}
function documentLineRow(line={}){return `<div class="document-line"><label>Código<input data-doc-field="code" value="${esc(line.code)}" maxlength="80"></label><label>Producto / detalle<input data-doc-field="description" value="${esc(line.description)}" maxlength="180"></label><label>Cant.<input data-doc-field="quantity" value="${esc(line.quantity)}" inputmode="decimal"></label><label>Unidad<input data-doc-field="unit" value="${esc(line.unit)}" maxlength="32"></label><label>Precio unit.<input data-doc-field="unit_price" value="${esc(line.unit_price)}" inputmode="decimal"></label><label>Importe<input data-doc-field="line_total" value="${esc(line.line_total)}" inputmode="decimal"></label><button type="button" class="danger remove-doc-line" aria-label="Quitar renglón">×</button></div>`;}
async function editDocument(id,created=null){
  let doc=created;if(!doc){try{doc=await api(`/documents/${id}`);}catch(e){toast(e.message);return;}}if(!doc)return;const data=doc.data||doc;
  const relationOptions=[['','Sin vincular'],...documents.filter(x=>x.id!==id).map(x=>[x.id,`${docTypeNames[x.document_type]||'Documento'} · ${x.supplier||'Sin proveedor'} · ${x.document_number||'s/n'}`])];
  const form=openDialog('Revisar documento',`<img class="document-preview" src="/api/documents/${esc(id)}/image" alt="Imagen original del documento"><p class="muted">La imagen se conserva privada. Revisá los datos: la lectura puede confundir números o productos.</p><div class="grid2"><label>Tipo<select name="document_type">${options(Object.entries(docTypeNames),data.document_type||doc.document_type)}</select></label>${field('supplier','Proveedor','text',data.supplier||doc.supplier||'','maxlength="180"')}</div><div class="grid2">${field('document_number','Número de documento','text',data.document_number||doc.document_number||'','maxlength="100"')}${field('document_date','Fecha','date',data.document_date||doc.document_date||'')}</div><div class="grid2">${field('total','Total del documento','text',data.total||'','inputmode="decimal"')}<label>Relacionado con<select name="related_document_id">${options(relationOptions,doc.related_document_id||'')}</select></label></div><label>Observaciones visibles<textarea name="notes" maxlength="1000">${esc(data.notes||'')}</textarea></label><div class="inline" style="justify-content:space-between"><h3>Renglones reconocidos</h3><button type="button" class="secondary" id="add-doc-line">+ Renglón</button></div><div id="document-lines">${(data.lines||[]).map(documentLineRow).join('')}</div><p class="muted">Vincular factura y remito evita confundirlos al revisar; ninguno genera un movimiento contable todavía.</p><button type="button" class="danger" id="delete-document">Eliminar borrador</button>`,'Guardar borrador',async(b)=>{
    const lines=[...$('#document-lines').querySelectorAll('.document-line')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-doc-field]')].map(input=>[input.dataset.docField,input.value])));
    const updated={document_type:b.document_type,supplier:b.supplier,document_number:b.document_number,document_date:b.document_date,total:b.total,notes:b.notes,lines};
    await api(`/documents/${id}`,{method:'PUT',body:{data:updated,related_document_id:b.related_document_id}});$('#dialog').close();await renderDocuments();toast('Borrador actualizado.');
  });
  $('#add-doc-line').onclick=()=>$('#document-lines').insertAdjacentHTML('beforeend',documentLineRow());
  $('#document-lines').onclick=e=>{if(e.target.closest('.remove-doc-line'))e.target.closest('.document-line').remove();};
  $('#delete-document').onclick=async()=>{if(!confirm('¿Eliminar el documento y su imagen?'))return;try{await api(`/documents/${id}`,{method:'DELETE'});$('#dialog').close();await renderDocuments();toast('Borrador eliminado.');}catch(e){toast(e.message);}};
}
