function importProducts(){
  let sheets=[],mapped=[],preview=null;
  const form=openDialog('Importar productos desde Excel',`<p class="note">Archivo .xlsx, hasta 3 MB y 300 productos. La primera fila debe tener encabezados. Los precios numéricos se leen tal como están; para texto usá formato argentino (1.234,50).</p><label>Archivo Excel<input id="excel-file" type="file" accept=".xlsx" required></label><div id="excel-mapping"></div><label class="check"><input type="checkbox" name="update_existing">Actualizar precios de productos existentes que coincidan por nombre</label><p class="muted">Por defecto, los productos existentes se omiten. El archivo se procesa en tu navegador y solo se envían los nombres y precios seleccionados.</p><div id="excel-preview"></div>`,'Revisar importación',async(b,f)=>{
    if(!sheets.length)throw Error('Primero elegí el archivo.');
    if(!preview){const sheet=sheets[Number($('#excel-sheet').value)],nameIndex=Number($('#excel-name').value),priceIndex=Number($('#excel-price').value);if(nameIndex===priceIndex)throw Error('Elegí columnas diferentes para nombre y precio.');
      mapped=sheet.data.slice(1).map((r,index)=>({source_row:index+2,name:r[nameIndex],price:r[priceIndex]})).filter(r=>r.name!=null||r.price!=null);
      preview=await api('/products/import',{method:'POST',body:{rows:mapped,update_existing:f.elements.update_existing.checked}});
      $('#excel-preview').innerHTML=`<div class="note">Nuevos: <strong>${preview.create}</strong> · Actualizaciones: <strong>${preview.update}</strong> · Omitidos: <strong>${preview.skip}</strong></div>${preview.errors.map(e=>`<p class="error">Fila ${e.row}: ${esc(e.error)}</p>`).join('')}<div class="scroll import-table"><table><thead><tr><th>Producto</th><th>Actual</th><th>Excel</th><th>Acción</th></tr></thead><tbody>${preview.items.map(r=>`<tr><td>${esc(r.name)}</td><td class="number">${r.old_price===null?'—':money(r.old_price)}</td><td class="number">${money(r.price)}</td><td>${{create:'Crear',update:'Actualizar',skip:'Omitir'}[r.action]}</td></tr>`).join('')}</tbody></table></div>`;
      f.querySelector('[type=submit]').textContent=preview.errors.length?'Revisar nuevamente':'Confirmar importación';if(preview.errors.length)preview=null;return;
    }
    if(!preview.create&&!preview.update)throw Error('No hay cambios para guardar.');
    const result=await api('/products/import',{method:'POST',headers:{'Idempotency-Key':f.operationId},body:{rows:mapped,update_existing:f.elements.update_existing.checked,confirm:true,fingerprint:preview.fingerprint}});
    $('#dialog').close();await refresh();toast(result.repeated?'La importación ya estaba guardada.':`Importación guardada: ${result.created} nuevos y ${result.updated} actualizados.`);
  });
  function resetPreview(){preview=null;$('#excel-preview').innerHTML='';form.querySelector('[type=submit]').textContent='Revisar importación';form.operationId=crypto.randomUUID();}
  function columns(){const sheet=sheets[Number($('#excel-sheet').value)],headers=sheet.data[0]||[];const opts=headers.map((v,i)=>[String(i),String(v??'Columna '+(i+1))]);$('#excel-columns').innerHTML=`<div class="grid2"><label>Columna producto<select id="excel-name">${options(opts,String(Math.max(0,headers.findIndex(v=>/nombre|producto|descripci/i.test(String(v))))))}</select></label><label>Columna precio<select id="excel-price">${options(opts,String(Math.max(0,headers.findIndex(v=>/precio|venta|importe/i.test(String(v))))))}</select></label></div>`;$('#excel-name').onchange=resetPreview;$('#excel-price').onchange=resetPreview;}
  $('#excel-file').onchange=async e=>{resetPreview();sheets=[];$('#excel-mapping').innerHTML='';const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const {readWorkbook}=await import('/excel.js');sheets=await readWorkbook(e.target.files[0]);$('#excel-mapping').innerHTML=`<label>Hoja<select id="excel-sheet">${options(sheets.map((s,i)=>[String(i),s.sheet]))}</select></label><div id="excel-columns"></div>`;columns();$('#excel-sheet').onchange=()=>{columns();resetPreview();};form.querySelector('.form-error').innerHTML='';}catch(e){form.querySelector('.form-error').innerHTML=`<p class="error">${esc(e.message)}</p>`;}finally{btn.disabled=false;}};
  form.elements.update_existing.onchange=resetPreview;
}
function login(initialized){
  $('#app').innerHTML=`<div class="login"><section class="login-story"><div class="brand"><img src="/icon.svg" alt="">PeloApp</div><div class="eyebrow">Menos vueltas. Más claridad.</div><h1>Cada consumo.<br>Cada cuenta.<br>Todo en orden.</h1><p>Una forma simple de gestionar las cuentas corrientes de tus kioscos, desde el celular o la computadora.</p><div class="login-visual"><span class="badge green">Tu gestión diaria</span><p><strong>Consumos → Cuentas → Cobros</strong></p><p>Precios originales y actualizados, con un historial que siempre podés consultar.</p></div></section><section class="login-form"><form id="login"><h2>${initialized?'Qué bueno verte de nuevo':'Configuremos tu primer acceso'}</h2><p class="muted">${initialized?'Ingresá con tu usuario para continuar.':'Creá el superadministrador de esta instalación.'}</p>${!initialized?field('token','Clave de instalación de Cloudflare','password','','required autocomplete="off"')+field('name','Tu nombre','text','','required'):''}${field('email','Correo electrónico','email','','required autocomplete="username"')}${field('password','Contraseña','password','','required maxlength="128" '+(!initialized?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'))}<div class="form-error" role="alert"></div><button type="submit">${initialized?'Ingresar':'Crear superadministrador'}</button><p class="muted" style="margin-top:20px;font-size:12px">Acceso privado · Cada persona ve sus colegios asignados.</p></form></section></div>`;
  $('#login').onsubmit=async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('[type=submit]');button.disabled=true;try{await api(initialized?'/login':'/setup',{method:'POST',body:b});if(!initialized){login(true);toast('Superadministrador creado. Ya podés ingresar.');}else await refresh();}catch(e){f.querySelector('.form-error').innerHTML=`<p class="error">${esc(e.message)}</p>`;}finally{button.disabled=false;}};
}
window.addEventListener('offline',()=>toast('Sin conexión. Conservá esta pantalla: la operación necesita confirmación del servidor.'));
window.addEventListener('online',()=>toast('Conexión recuperada. Podés reintentar la operación.'));
try { const status=await api('/status'); if(!status.initialized)login(false);else{try{await refresh();}catch{login(true);}} }
catch(e){$('#app').innerHTML=`<div class="login-form"><div><h1>PeloApp está preparándose</h1><p class="error">${esc(e.message)}</p><p class="muted">Si es la primera instalación, aplicá las migraciones D1 y configurá la clave de instalación.</p><button id="retry">Reintentar</button></div></div>`;$('#retry').onclick=()=>location.reload();}
